Hi @Maaark, I just made a showMorePaginator widget that you can see in action here: http://codepen.io/vvo/pen/jAwXoo

Here's the code:

``` js
var paginatorShowMore = {
  init: function(args) {
    var helper = args.helper;
    document
      .querySelector('#show-more')
      .addEventListener('click', function() {
        helper
          .setQueryParameter('hitsPerPage',
          helper.getQueryParameter('hitsPerPage') + defaultHitsPerPage
        )
        .search();
      });
  },
  render: function(args) {
    var helper = args.helper;
    var currentHitsPerPage = helper.getQueryParameter('hitsPerPage');
    if (currentHitsPerPage > defaultHitsPerPage) {
      var hitsIndexToScroll = currentHitsPerPage - defaultHitsPerPage;
      document
        .querySelectorAll('.ais-hits--item')
        [hitsIndexToScroll].scrollIntoView();
        // if we are showing 50 hits, make sure
        // the 39th hit is visible in the viewport
        // this also handles url refresh/url copy paste
    }
  }
};

search.addWidget(paginatorShowMore);
```

You should be able to throw a lot of your ccurrent code, let me know how it goes.
